// Exercise current exported authoring code against the installed-plugin capture
// in a disposable project. Never change the WordPress fixture or saved build.
import assert from'node:assert/strict';import{mkdtemp,cp,readFile,writeFile,rm}from'node:fs/promises';import{tmpdir}from'node:os';import path from'node:path';import{load}from'cheerio';import{parseContent,YAML}from'../../scripts/source-project.mjs';import{run}from'../../engine/pipeline.mjs';
const source=path.resolve(process.argv[2]||'artifacts/platform/events/project'),dir=await mkdtemp(path.join(tmpdir(),'installed-event-authoring-'));
try{
 await cp(source,dir,{recursive:true,filter:entry=>!['output','.ssg-output','.ssg-content','.ssg-templates'].includes(path.basename(entry))});
 await cp(new URL('../../vendor/export-source.mjs',import.meta.url),path.join(dir,'scripts/source.mjs'));
 for(const name of ['events-export.mjs','event-presentation.mjs','seo-export.mjs'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(dir,'scripts',name));
 const routes=JSON.parse(await readFile(path.join(dir,'routes.json'))),record=routes.find(r=>r.route==='/event/evening-concert/');assert.ok(record);const sourceFile=path.join(source,'content',record.collection,record.slug+'.md'),sourceBefore=await readFile(sourceFile,'utf8');const file=path.join(dir,'content',record.collection,record.slug+'.md'),parsed=parseContent(await readFile(file,'utf8'),file);parsed.meta.event.start='2028-01-08 10:00:00';parsed.meta.event.end='2028-01-08 12:00:00';await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body);
 await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});
 const archive=load(await readFile(path.join(dir,'output/events/index.html'),'utf8'));assert.deepEqual(archive('.tribe-events-calendar-list__month-separator time').map((_,e)=>archive(e).text().trim()).get(),['December 2027','January 2028']);assert.equal(archive('.migration-pagination').length,0);assert.deepEqual(archive('.tribe-events-calendar-list__event-date-tag-daynum').map((_,e)=>archive(e).text().trim()).get(),['31','8']);
 const detail=load(await readFile(path.join(dir,'output/event/evening-concert/index.html'),'utf8'));assert.equal(detail('.tribe-event-date-start').text(),'January 8, 2028 @ 10:00 am');assert.equal(detail('.tribe-event-time').text(),'12:00 pm');assert.equal(detail('.tribe-events-start-date').text(),'January 8, 2028');assert.equal(detail('.tribe-events-start-time').text(),'10:00 am - 12:00 pm');
 const report=JSON.parse(await readFile(path.join(dir,'events-report.json'))),event=report.pages.find(p=>p.route==='/event/evening-concert/');assert.deepEqual(event.presentationIssues,[]);const ics=await readFile(path.join(dir,'output',event.calendar),'utf8');assert.match(ics,/DTSTART:20280108T150000Z/);assert.match(ics,/DTEND:20280108T170000Z/);assert.match(detail('script[type="application/ld+json"]').text(),/2028-01-08T15:00:00Z/);assert.match(archive('script[type="application/ld+json"]').text(),/2028-01-08T15:00:00Z/);
 assert.equal(await readFile(sourceFile,'utf8'),sourceBefore);
 console.log(JSON.stringify({status:'passed',sourceProject:source,scope:'Installed captured theme and plugin; copied project with current bundled authoring runtime',localDates:['2028-01-08 10:00:00','2028-01-08 12:00:00'],utcDates:['2028-01-08 15:00:00','2028-01-08 17:00:00'],monthGroups:['December 2027','January 2028'],presentationIssues:event.presentationIssues,sourceMutated:false}));
}finally{await rm(dir,{recursive:true,force:true});}
